from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # Solid 3x3 tile with only its center absent: mark its center.
            if r1-r0 == 2 and c1-c0 == 2:
                expected={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)}
                if set(cells) == expected - {(r0+1,c0+1)}:
                    out[r0+1][c0+1] = 7
                continue
            # Hollow rectangular frame: color the enclosed area.
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = ({(r0,x) for x in range(c0,c1+1)} |
                         {(r1,x) for x in range(c0,c1+1)} |
                         {(y,c0) for y in range(r0,r1+1)} |
                         {(y,c1) for y in range(r0,r1+1)})
            if set(cells) == perimeter:
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x] = 2
    return out

